import numpy as np, collections, math

def transform(grid):
    a=np.array(grid, dtype=int)
    h,w=a.shape
    best=None
    for color in np.unique(a):
        row_idx=[r for r in range(h) if np.mean(a[r,:]==color)>=0.65]
        col_idx=[c for c in range(w) if np.mean(a[:,c]==color)>=0.65]
        def regscore(ix, n):
            if len(ix)<2: return 0.0
            ds=np.diff(ix)
            # equal spacing is the strongest sign of repeated grid lines
            regular=float(np.max(np.bincount(ds))/len(ds))
            density=len(ix)/n
            return regular*(1-density)
        score=regscore(row_idx,h)+regscore(col_idx,w)
        if best is None or score>best[0]: best=(score,int(color),row_idx,col_idx)
    _, line, rows, cols=best
    marks=[(ri,ci) for ri,r in enumerate(rows) for ci,c in enumerate(cols) if a[r,c]!=line]
    if not marks:
        return [[line]]
    rlo=min(x[0] for x in marks); rhi=max(x[0] for x in marks)
    clo=min(x[1] for x in marks); chi=max(x[1] for x in marks)
    rows=rows[rlo:rhi+1]; cols=cols[clo:chi+1]
    marker_positions={(r,c) for r in rows for c in cols}
    counts=collections.Counter(int(x) for x in a.flat if int(x)!=line)
    # Strip the sparse values written at line intersections before finding the field color.
    for r in rows:
        for c in cols:
            v=int(a[r,c])
            if v!=line: counts[v]-=1
    background=max(counts, key=counts.get) if counts else line
    out=[]
    for i in range(len(rows)-1):
        row=[]
        for j in range(len(cols)-1):
            vals=[int(a[rows[i],cols[j]]),int(a[rows[i],cols[j+1]]),int(a[rows[i+1],cols[j]]),int(a[rows[i+1],cols[j+1]])]
            row.append(vals[0] if all(v==vals[0] for v in vals) else background)
        out.append(row)
    return out

